package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var loanRec LoanRec

var loanFile *bufio.Scanner
var loanFileHandle *os.File
var inputDone bool

func formatCount(v int64, digits int) string {
	s := fmt.Sprintf("%d", v)
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func formatEdited(pic string, val decimal.Decimal) string {
	// count integer and fractional placeholder slots
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracSlots++
		}
	}

	neg := val.IsNegative()
	if neg {
		val = val.Neg()
	}

	// scaled integer = val * 10^fracSlots truncated
	var scaled decimal.Decimal
	if fracSlots > 0 {
		scaled = val.Shift(int32(fracSlots)).Truncate(0)
	} else {
		scaled = val.Truncate(0)
	}
	// overflow: keep low-order digits that fit
	// total slots = intSlots + fracSlots
	totalSlots := intSlots + fracSlots
	// compute 10^totalSlots as decimal for modulo
	pow10 := decimal.NewFromInt(1)
	for i := 0; i < totalSlots; i++ {
		pow10 = pow10.Mul(decimal.NewFromInt(10))
	}
	// if scaled >= pow10, keep modulo (low-order)
	if totalSlots > 0 && scaled.Cmp(pow10) >= 0 {
		scaled = scaled.Mod(pow10)
	}
	// build digits string with totalSlots digits, zero padded
	// scaled is integer
	sDigits := scaled.StringFixed(0) // no decimals, no exponent
	// StringFixed may include minus; we already abs
	if len(sDigits) < totalSlots {
		sDigits = strings.Repeat("0", totalSlots-len(sDigits)) + sDigits
	} else if len(sDigits) > totalSlots {
		sDigits = sDigits[len(sDigits)-totalSlots:]
	}
	var intDigits string
	var fracDigits string
	if fracSlots > 0 {
		if totalSlots > 0 {
			intDigits = sDigits[:intSlots]
			fracDigits = sDigits[intSlots:]
		} else {
			fracDigits = sDigits
		}
	} else {
		intDigits = sDigits
		fracDigits = ""
	}
	// Build output array same length as pic
	out := make([]byte, len(pic))
	intIdx := 0
	fracIdx := 0
	for i := 0; i < len(pic); i++ {
		c := pic[i]
		switch c {
		case 'Z', '9':
			if i < len(intPic) || dotIdx == -1 {
				// integer part placeholder (before dot)
				// Need to know if this position is integer or fractional based on dot
				// Simpler: if i < dotIdx or dotIdx==-1 -> integer
				if dotIdx == -1 || i < dotIdx {
					out[i] = intDigits[intIdx]
					intIdx++
				} else {
					// shouldn't happen
					out[i] = intDigits[intIdx]
					intIdx++
				}
			} else {
				out[i] = fracDigits[fracIdx]
				fracIdx++
			}
		case ',':
			out[i] = ','
		case '.':
			out[i] = '.'
		default:
			out[i] = c
		}
	}
	// Zero suppression for leading Z's
	// Find suppression zone: from start up to last Z that is still leading
	// Suppression active until we encounter a non-zero digit in a Z or any '9'
	suppressing := true
	for i := 0; i < len(pic); i++ {
		c := pic[i]
		if c == '.' {
			suppressing = false
			continue
		}
		if !suppressing {
			continue
		}
		if c == 'Z' {
			if out[i] == '0' {
				out[i] = ' '
			} else {
				suppressing = false
			}
		} else if c == '9' {
			// mandatory digit ends suppression
			suppressing = false
		} else if c == ',' {
			// comma inside suppressed region becomes space
			// if still suppressing, it means all significant digits to left are zero
			// So turn to space
			out[i] = ' '
		}
	}
	// re-evaluate commas that are now between spaces and digits? Already handled.
	result := string(out)
	_ = neg
	return result
}

func parseLoanLine(line string) LoanRec {
	// pad to 21
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	}
	if len(line) > 21 {
		line = line[:21]
	}
	acct := line[0:6]
	prinStr := line[6:15]   // 9 digits
	rateStr := line[15:19]  // 4 digits
	yearsStr := line[19:21] // 2 digits

	var prin decimal.Decimal
	var rate decimal.Decimal
	var years int64

	// helper to parse digits only
	trimP := strings.TrimSpace(prinStr)
	if trimP == "" {
		prin = decimal.NewFromInt(0)
	} else {
		// digits only
		n := int64(0)
		for _, ch := range prinStr {
			if ch >= '0' && ch <= '9' {
				n = n*10 + int64(ch-'0')
			}
		}
		prin = decimal.New(n, -2)
	}
	trimR := strings.TrimSpace(rateStr)
	if trimR == "" {
		rate = decimal.NewFromInt(0)
	} else {
		n := int64(0)
		for _, ch := range rateStr {
			if ch >= '0' && ch <= '9' {
				n = n*10 + int64(ch-'0')
			}
		}
		rate = decimal.New(n, -2)
	}
	trimY := strings.TrimSpace(yearsStr)
	if trimY == "" {
		years = 0
	} else {
		n := int64(0)
		for _, ch := range yearsStr {
			if ch >= '0' && ch <= '9' {
				n = n*10 + int64(ch-'0')
			}
		}
		years = n
	}
	return LoanRec{
		LrAcct:      acct,
		LrPrincipal: prin,
		LrRate:      rate,
		LrYears:     years,
	}
}

func mainPara() {
	openInput()
	performReadPara()
	for !inputDone {
		performProcessPara()
	}
	closeLoanFile()
	performSummaryPara()
}

func openInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as EOF
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	loanFileHandle = f
	loanFile = bufio.NewScanner(f)
	// allow long lines
	loanFile.Split(bufio.ScanLines)
}

func closeLoanFile() {
	if loanFileHandle != nil {
		loanFileHandle.Close()
	}
}

func performReadPara() {
	readPara()
}

func readPara() {
	if loanFile == nil {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	if loanFile.Scan() {
		line := loanFile.Text()
		loanRec = parseLoanLine(line)
	} else {
		inputDone = true
		WsEofFlag = "Y"
	}
}

func performProcessPara() {
	processPara()
}

func processPara() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	// target scale 2
	// compute with decimal then round
	prod := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears))
	// divide by 100 via Shift(-2)
	div := prod.Shift(-2)
	WsInterest = div.Round(2)
	// truncate / wrap to PIC 9(9)V99 : keep low-order 9 integer digits + 2 dec
	// Implement overflow truncation for storage
	WsInterest = storeField(WsInterest, 9, 2)

	WsTotal = WsTotal.Add(WsInterest)
	WsTotal = storeField(WsTotal, 11, 2)

	WsCount = WsCount + 1
	// overflow for count PIC 9(5): keep low 5 digits
	if WsCount > 99999 {
		WsCount = WsCount % 100000
	}

	WsPrinEd = formatEdited("Z,ZZZ,ZZ9.99", loanRec.LrPrincipal)
	WsIntEd = formatEdited("ZZZ,ZZZ,ZZ9.99", WsInterest)
	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)
	performReadPara()
}

func storeField(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// truncate toward zero to scale, then modulo 10^(intDigits+scale)?? For positive numbers
	// First truncate
	v = v.Truncate(scale)
	neg := v.IsNegative()
	abs := v.Abs()
	powInt := decimal.NewFromInt(1)
	for i := 0; i < intDigits; i++ {
		powInt = powInt.Mul(decimal.NewFromInt(10))
	}
	// max integer part allowed
	// if abs >= powInt (integer part) then keep low-order digits
	// integer part = abs.Truncate(0)
	intPart := abs.Truncate(0)
	if intPart.Cmp(powInt) >= 0 {
		// keep low-order digits: modulo powInt for integer part, preserve fractional
		frac := abs.Sub(intPart)
		newInt := intPart.Mod(powInt)
		abs = newInt.Add(frac)
		if neg {
			abs = abs.Neg()
		}
		v = abs
	}
	return v
}

func performSummaryPara() {
	summaryPara()
}

func summaryPara() {
	WsTotalEd = formatEdited("ZZ,ZZZ,ZZZ,ZZ9.99", WsTotal)
	countStr := formatCount(WsCount, 5)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func main() {
	mainPara()
}
